"use client";

import { BLUEPRINT_SEED } from "@/app/lib/blueprintSeed";
import { useCountUp } from "@/app/lib/useCountUp";
import { formatINR } from "@/app/lib/formatINR";
import { motion } from "framer-motion";
import { usePrefersReducedMotion } from "@/app/lib/usePrefersReducedMotion";
import { TiltCard } from "./TiltCard";

/** Total debt — principal outstanding, counting up on load. Neutral bone,
    not red: this is a figure, not an "act now" state. Seed data (P8). */
export function DebtReadout() {
  const reduce = usePrefersReducedMotion();
  const shown = useCountUp(BLUEPRINT_SEED.totalDebt);

  return (
    <TiltCard>
      <div aria-label="Total debt">
        <p className="num text-[10px] tracking-[0.24em] text-dim">TOTAL DEBT</p>
        <p className="num mt-1 text-3xl font-bold text-bone">{formatINR(Math.round(shown))}</p>
        <p className="num mt-1 text-[10px] text-dim">principal outstanding</p>
        <motion.div
          className="mt-4 h-[3px] rounded bg-dim/50"
          initial={{ scaleX: reduce ? 1 : 0 }}
          animate={{ scaleX: 1 }}
          style={{ transformOrigin: "left" }}
          transition={{ duration: 1.1, ease: [0.16, 1, 0.3, 1] }}
        />
      </div>
    </TiltCard>
  );
}
